#include <iostream>
#include <cctype>

int main() {
    char ch = ' ';
    if (std::cin >> ch) {
        std::cout << "Character: " << ch << "\n";
        if (std::islower(static_cast<unsigned char>(ch))) {
            std::cout << "Type: lowercase\n";
            std::cout << "Upper: " << static_cast<char>(std::toupper(static_cast<unsigned char>(ch))) << "\n";
        } else if (std::isupper(static_cast<unsigned char>(ch))) {
            std::cout << "Type: uppercase\n";
            std::cout << "Lower: " << static_cast<char>(std::tolower(static_cast<unsigned char>(ch))) << "\n";
        } else if (std::isdigit(static_cast<unsigned char>(ch))) {
            std::cout << "Type: digit\n";
        } else {
            std::cout << "Type: other\n";
        }
    }
    return 0;
}
